def combinations2(n):
    if n < 2:
        return 0
    return n * (n - 1) // 2

N = 199

# We minimize f(k) = C(N-k, 2) + C(k, 2) for k in {0, 1, ..., N-1}
# The minimum occurs when N-k and k are closest, which is k=99 or k=100.

k1 = 99
k2 = 100

def f(k):
    return combinations2(N - k) + combinations2(k)

result1 = f(k1)
result2 = f(k2)

print(f"f(99) = {result1}")
print(f"f(100) = {result2}")

